FORM_NOTES = {
 "article": "the response should be set out as an article, with a suitable headline and possibly subheadings, an engaging introduction, developed paragraphs and a conclusion.",
 "speech": "the response should be set out as a speech, with a clear opening that addresses the audience, development of points using rhetorical techniques, and a strong conclusion.",
 "letter": "the response should be set out as a formal letter, with an appropriate greeting, a clear statement of purpose, developed paragraphs and a suitable sign-off.",
 "guide": "the response should be organised as a guide, using a title, headings, subheadings, lists or numbered steps, with a clear introduction and conclusion.",
 "review": "the response should be set out as a review, with a title, an introduction, description and evaluation, and a clear final judgement or recommendation.",
 "leaflet": "the response should be organised as the text of a leaflet, using a title, headings, short sections, bullet points or slogans, and a clear call to action or contact details.",
}
FORM_IDEA = {
 "article": "use features such as a striking headline, rhetorical questions, anecdotes and a confident authorial voice",
 "speech": "use direct address, inclusive pronouns, repetition, lists of three and a memorable ending",
 "letter": "adopt a polite, formal register, refer to the issue raised and end with a clear request or conclusion",
 "guide": "address the reader directly, using imperatives, practical examples and a helpful, reassuring tone",
 "review": "combine description with clear evaluative language, perhaps using a rating or recommendation",
 "leaflet": "use a confident, accessible tone with imperatives, persuasive language and clear organisational features",
}


def _bul(intro, items):
    return intro + "\n" + "\n".join("• " + i for i in items + ["any other points you wish to make."])


def writing_tasks():
    out = []
    for i, (key, stmt, title, b1, b2, ideas, hard, proposal) in enumerate(ISSUES):
        diff = "7-9" if hard else "4-6"
        pub = PUBLICATIONS[i % len(PUBLICATIONS)]
        if i % 2 == 0:
            text = (f"‘{stmt}’\n\nWrite an article for {pub} in which you give your views on this statement.\n\n" +
                    _bul("Your article may include:", [b1, b2]))
        else:
            text = (f"{pub[0].upper() + pub[1:]} is publishing a series of articles with the title ‘{title}’.\n\n"
                    f"Write your article for the series.\n\n" + _bul("Your article may include:", [b1, b2]))
        out.append(dict(form="article", key=key, issue=key, text=text, difficulty=diff,
                        purpose="to write an article that informs and argues, expressing a clear point of view.",
                        audience=f"readers of {pub}. There should be an attempt to engage and influence them.",
                        form_note=FORM_NOTES["article"],
                        ideas=["explore what the statement or title means"] + ideas + [FORM_IDEA["article"], "agree, disagree or take a balanced view, provided the view is clearly expressed"]))
        aud = AUDIENCES[(i * 5 + 1) % len(AUDIENCES)]
        text = (f"‘{stmt}’\n\nWrite the text for a speech to be given to {aud} in which you explain your views on this statement.\n\n" +
                _bul("Your speech may include:", [b1, b2]))
        out.append(dict(form="speech", key=key, issue=key, text=text, difficulty="7-9" if (hard or i % 3 == 0) else "4-6",
                        purpose="to write a speech that argues and persuades.",
                        audience=f"{aud}. The speech should engage the listeners and try to win them over.",
                        form_note=FORM_NOTES["speech"],
                        ideas=ideas + [FORM_IDEA["speech"], "acknowledge and answer opposing views"]))
        if proposal:
            text = (f"Your headteacher is considering {proposal}.\n\nWrite a letter to your headteacher in which you give your views on this idea.\n\n" +
                    _bul("Your letter may include:", ["how this idea would affect students and the school", "what you think should happen instead, or how the idea could be improved"]))
            aud_l = "the headteacher, so the register should be formal and respectful."
        else:
            paper = ["your local newspaper", "a national newspaper", "a magazine you read"][i % 3]
            text = (f"A recent article in {paper} claimed that ‘{stmt[0].lower() + stmt[1:]}’\n\n"
                    f"Write a letter to the editor of {paper.replace('your ', 'the ').replace('a ', 'the ', 1)} in which you respond to this claim.\n\n" +
                    _bul("Your letter may include:", [b1, b2]))
            aud_l = "the editor and readers of the publication, so the register should be formal."
        out.append(dict(form="letter", key=key, issue=key, text=text, difficulty=diff,
                        purpose="to write a letter that responds to a proposal or claim and argues a point of view.",
                        audience=aud_l, form_note=FORM_NOTES["letter"],
                        ideas=ideas + [FORM_IDEA["letter"]]))
    for key, setup, instr, aud, bl, ideas, hard in GUIDES:
        out.append(dict(form="guide", key=key, text=f"{setup}\n\n{instr}\n\n" + _bul("Your guide may include:", bl),
                        difficulty="7-9" if hard else "4-6", purpose="to write a guide that informs and advises.",
                        audience=f"{aud}. The guide should be clear, helpful and engaging.", form_note=FORM_NOTES["guide"],
                        ideas=ideas + [FORM_IDEA["guide"]]))
    for key, setup, instr, bl, ideas, hard in REVIEWS:
        out.append(dict(form="review", key=key, text=f"{setup}\n\n{instr}\n\n" + _bul("Your review may include:", bl),
                        difficulty="7-9" if hard else "4-6", purpose="to write a review that informs, describes and evaluates.",
                        audience="readers of the publication or website, who want an engaging, honest judgement.",
                        form_note=FORM_NOTES["review"], ideas=ideas + [FORM_IDEA["review"]]))
    for key, setup, instr, aud, bl, ideas, hard in LEAFLETS:
        out.append(dict(form="leaflet", key=key, text=f"{setup}\n\n{instr}\n\n" + _bul("Your leaflet may include:", bl),
                        difficulty="7-9" if hard else "4-6", purpose="to write the text of a leaflet that informs and persuades.",
                        audience=f"{aud}. The leaflet should capture their attention and encourage action.",
                        form_note=FORM_NOTES["leaflet"], ideas=ideas + [FORM_IDEA["leaflet"]]))
    return out
